import { analyzeId, analyzeText } from './analyzer.mjs';
import { isDecimalIntegerString, parseDecimalInteger } from './bigint-utils.mjs';
import {
  MATCH_NONE,
  PhraseQuery,
  PrefixQuery,
  TermQuery,
  NumericRangeQuery,
  NumericTermQuery,
  TextRangeQuery,
  NotQuery,
  combineAnd,
  combineOr,
} from './query.mjs';

function tokenizeQuery(input) {
  const tokens = [];
  let index = 0;

  while (index < input.length) {
    const character = input[index];

    if (/\s/u.test(character)) {
      index += 1;
      continue;
    }

    if (character === '(') {
      tokens.push({ type: 'LPAREN' });
      index += 1;
      continue;
    }

    if (character === ')') {
      tokens.push({ type: 'RPAREN' });
      index += 1;
      continue;
    }

    if (character === ':') {
      tokens.push({ type: 'COLON' });
      index += 1;
      continue;
    }

    if (character === '[' || character === '{') {
      const closing = character === '[' ? ']' : '}';
      let cursor = index + 1;

      while (cursor < input.length && input[cursor] !== closing) {
        cursor += 1;
      }

      const content = input.slice(index + 1, cursor);
      tokens.push({
        type: 'RANGE',
        content,
        inclusiveStart: character === '[',
        inclusiveEnd: cursor < input.length && input[cursor] === ']',
      });
      index = cursor < input.length ? cursor + 1 : cursor;
      continue;
    }

    if (character === '"') {
      let cursor = index + 1;
      let phrase = '';

      while (cursor < input.length) {
        const current = input[cursor];
        if (current === '\\' && cursor + 1 < input.length) {
          phrase += input[cursor + 1];
          cursor += 2;
          continue;
        }

        if (current === '"') {
          break;
        }

        phrase += current;
        cursor += 1;
      }

      tokens.push({ type: 'PHRASE', value: phrase });
      index = cursor < input.length ? cursor + 1 : cursor;
      continue;
    }

    let cursor = index;
    while (
      cursor < input.length
      && !/\s/u.test(input[cursor])
      && !['(', ')', ':', '[', ']', '{', '}', '"'].includes(input[cursor])
    ) {
      cursor += 1;
    }

    tokens.push({ type: 'WORD', value: input.slice(index, cursor) });
    index = cursor;
  }

  return tokens;
}

function canStartClause(token) {
  return token !== undefined && ['LPAREN', 'WORD', 'PHRASE', 'RANGE'].includes(token.type);
}

function stripOuterQuotes(value) {
  if (value.length >= 2 && value.startsWith('"') && value.endsWith('"')) {
    return value.slice(1, -1);
  }

  return value;
}

function parseRangeBounds(content) {
  const match = content.trim().match(/^(.*?)\s+TO\s+(.*)$/iu);
  if (!match) {
    return null;
  }

  return {
