class InternalQueryParser {
  constructor(defaultField, schema, tokens) {
    this.defaultField = defaultField;
    this.schema = schema;
    this.tokens = tokens;
    this.index = 0;
  }

  peek(offset = 0) {
    return this.tokens[this.index + offset];
  }

  consume() {
    const token = this.tokens[this.index];
    this.index += 1;
    return token;
  }

  matchOperator(name) {
    const token = this.peek();
    if (token?.type === 'WORD' && token.value === name) {
      this.consume();
      return true;
    }

    return false;
