  parse() {
    return this.parseOr(this.defaultField) ?? MATCH_NONE;
  }

  parseOr(defaultField) {
    let clause = this.parseAnd(defaultField);

    while (this.matchOperator('OR')) {
      const right = this.parseAnd(defaultField);
      clause = combineOr([clause, right]);
