    }

    if (this.peek()?.type === 'PHRASE') {
      const token = this.consume();
      return this.buildPhraseClause(fieldName, token.value);
    }

    if (this.peek()?.type === 'RANGE') {
      const token = this.consume();
      return this.buildRangeClause(fieldName, token);
    }

    if (this.peek()?.type === 'WORD') {
      const token = this.consume();
      return this.buildWordClause(fieldName, token.value);
    }

    return null;
  }

  buildWordClause(fieldName, rawValue) {
    const field = this.schema.get(fieldName);
    if (!field) {
      return null;
    }

    if (field.kind === 'NUMERIC') {
      if (!isDecimalIntegerString(rawValue)) {
        return null;
      }
      return new NumericTermQuery(fieldName, parseDecimalInteger(rawValue));
    }

    if (rawValue === '*') {
      return null;
    }

    if (rawValue.endsWith('*')) {
      const prefixTokens = analyzeForField(field, rawValue.slice(0, -1));
      if (prefixTokens.length === 0) {
        return null;
      }

      const clauses = prefixTokens.slice(0, -1).map((term) => new TermQuery(fieldName, term));
      clauses.push(new PrefixQuery(fieldName, prefixTokens[prefixTokens.length - 1]));
      return combineAnd(clauses);
    }

    const terms = analyzeForField(field, rawValue);
    return combineAnd(terms.map((term) => new TermQuery(fieldName, term)));
  }

  buildPhraseClause(fieldName, rawValue) {
    const field = this.schema.get(fieldName);
    if (!field || field.kind === 'NUMERIC') {
      return null;
    }

    const terms = analyzeForField(field, rawValue);
    if (terms.length === 0) {
      return null;
    }

    return new PhraseQuery(fieldName, terms);
  }

  buildRangeClause(fieldName, rangeToken) {
    const field = this.schema.get(fieldName);
    if (!field) {
      return null;
    }

    const bounds = parseRangeBounds(rangeToken.content);
    if (!bounds) {
      return null;
    }

    if (field.kind === 'NUMERIC') {
      const start = bounds.startRaw === '*' ? null : (
        isDecimalIntegerString(bounds.startRaw) ? parseDecimalInteger(bounds.startRaw) : null
