      const end = bounds.endRaw === '*' ? null : (
        isDecimalIntegerString(bounds.endRaw) ? parseDecimalInteger(bounds.endRaw) : null
      );

      if ((bounds.startRaw !== '*' && start === null) || (bounds.endRaw !== '*' && end === null)) {
        return null;
      }

      return new NumericRangeQuery(
        fieldName,
        start,
        end,
        rangeToken.inclusiveStart,
        rangeToken.inclusiveEnd,
      );
    }

    const startTerms = analyzeForField(field, bounds.startRaw);
    const endTerms = analyzeForField(field, bounds.endRaw);
    if (bounds.startRaw !== '*' && startTerms.length === 0) {
      return null;
    }
    if (bounds.endRaw !== '*' && endTerms.length === 0) {
      return null;
    }

    return new TextRangeQuery(
      fieldName,
      bounds.startRaw === '*' ? null : startTerms[0],
      bounds.endRaw === '*' ? null : endTerms[0],
      rangeToken.inclusiveStart,
      rangeToken.inclusiveEnd,
    );
  }
