import { analyzeId, analyzeText } from './analyzer.mjs';
import { toBigIntValue } from './bigint-utils.mjs';

function prepareDocument(schema, values) {
  const stored = {};
  const indexed = {};

  for (const [fieldName, field] of schema.entries()) {
    if (!Object.prototype.hasOwnProperty.call(values, fieldName)) {
      continue;
    }

    if (field.kind === 'NUMERIC') {
      const numericValue = toBigIntValue(values[fieldName]);
      indexed[fieldName] = numericValue;
      if (field.stored) {
        stored[fieldName] = numericValue;
      }
      continue;
    }

    const textValue = String(values[fieldName]);
    indexed[fieldName] = field.kind === 'ID' ? analyzeId(textValue) : analyzeText(textValue);
    if (field.stored) {
      stored[fieldName] = textValue;
    }
  }

  return { indexed, stored };
}

class Writer {
  constructor(index) {
    this.index = index;
    this.pending = [];
  }

  add_document(values) {
    this.pending.push(prepareDocument(this.index.schema, values));
  }

  commit() {
    this.index.documents.push(...this.pending);
    this.pending = [];
  }
}

class Searcher {
  constructor(index) {
    this.index = index;
  }

  search(query, limit = 10) {
    const results = [];

    for (const document of this.index.documents) {
      if (query.matches(document)) {
        results.push(document.stored);
        if (results.length >= limit) {
          break;
        }
      }
    }

    return results;
  }
}

class Index {
  constructor(directory, schema) {
    this.directory = directory;
    this.schema = schema;
    this.documents = [];
  }

  writer() {
    return new Writer(this);
  }

  searcher() {
    return new Searcher(this);
  }
}

export function create_in(directory, schema) {
  return new Index(directory, schema);
}

